def subscriptions_to_mutes(apps, schema_editor):
    """Users with opt-in subscriptions get mutes for catalog feeds they skipped."""
    Subscription = apps.get_model("news", "Subscription")
    Feed = apps.get_model("news", "Feed")
    FeedMute = apps.get_model("news", "FeedMute")

    catalog = list(
        Feed.objects.filter(
            is_active=True,
            owner__isnull=True,
            kind__in=["curated", "recommended"],
        ).values_list("id", flat=True)
    )
    if not catalog:
        return

    user_ids = Subscription.objects.order_by().values_list("user_id", flat=True).distinct()
    mutes = []
    for user_id in user_ids:
        subscribed = set(
            Subscription.objects.filter(user_id=user_id).values_list("feed_id", flat=True)
        )
        for feed_id in catalog:
            if feed_id not in subscribed:
                mutes.append(FeedMute(user_id=user_id, feed_id=feed_id))
    if mutes:
        FeedMute.objects.bulk_create(mutes, ignore_conflicts=True)


def reverse_mutes(apps, schema_editor):
    FeedMute = apps.get_model("news", "FeedMute")
    FeedMute.objects.all().delete()


